def get_repo_url(repo: "Repo") -> str:
    from dulwich.porcelain import get_remote_repo

    from dvc.env import DVC_EXP_GIT_REMOTE

    repo_url = os.getenv(
        DVC_EXP_GIT_REMOTE, repo.config.get("exp", {}).get("git_remote")
    )
    if repo_url:
        try:
            _, repo_url = get_remote_repo(repo.scm.dulwich.repo, repo_url)
        except IndexError:
            pass
    return repo_url

def save_config(self, hostname, token):
    with self.config.edit("global") as conf:
        conf["studio"]["token"] = token
        conf["studio"]["url"] = hostname
        if "auto_push" not in conf["exp"]:
            conf["exp"]["auto_push"] = True

