def save_config(self, hostname, token):
    with self.config.edit("global") as conf:
        # Save to feature section (new way)
        conf["feature"]["studio_token"] = token
        conf["feature"]["studio_url"] = hostname

        # Remove from studio section if it exists (old way)
        if "studio" in conf and "token" in conf["studio"]:
            del conf["studio"]["token"]
        if "studio" in conf and "url" in conf["studio"]:
            del conf["studio"]["url"]

        if "auto_push" not in conf["exp"]:
            conf["exp"]["auto_push"] = True

