class CmdStudioLogout(CmdConfig):
    def run(self):
        from dvc.ui import ui
        from dvc.utils.studio import get_studio_config

        studio_config = get_studio_config(self.config)
        if "token" not in studio_config:
            ui.error_write(
                "Not logged in to Studio. Log in with 'dvc studio login'."
            )
            return 1

        with self.config.edit("global") as conf:
            # Remove from feature section (new way)
            if "feature" in conf and "studio_token" in conf["feature"]:
                del conf["feature"]["studio_token"]

            # Remove from studio section (old way)
            if "studio" in conf and "token" in conf["studio"]:
                del conf["studio"]["token"]

        ui.write("Logged out from Studio (you can log back in with 'dvc studio login')")
        return 0

